-- Fen 4
DELETE FROM mufredat WHERE ders='Fen Bilimleri' AND sinif=4;


-- Sosyal 4
DELETE FROM mufredat WHERE ders='Sosyal Bilgiler' AND sinif=4;


-- Fen 5
DELETE FROM mufredat WHERE ders='Fen Bilimleri' AND sinif=5;


-- Sosyal 5
DELETE FROM mufredat WHERE ders='Sosyal Bilgiler' AND sinif=5;


-- Mat 5 (Kesirler ve Cebirsel Dusunme satirlari plan konusu degil)
DELETE FROM mufredat WHERE ders='Matematik' AND sinif=5 AND unite IN ('Sayilar ve Nicelikler','Islemlerle Cebirsel Dusunme');


-- Mat 6
DELETE FROM mufredat WHERE ders='Matematik' AND sinif=6 AND unite IN ('Sayilar ve Nicelikler','Istatistiksel Arastirma Sureci');


-- Fen 8
DELETE FROM mufredat WHERE ders='Fen Bilimleri' AND sinif=8 AND unite IN ('Basinc','Madde ve Endustri','Enerji Donusumleri ve Cevre Bilimi');

